import sqlite3
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Optional

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("crm")
DB_PATH = "crm.db"


@dataclass
class StageUpdateResult:
    deal_id: int
    old_stage: Optional[str]
    new_stage: str
    updated: bool


@mcp.tool()
def update_deal_stage(deal_id: int, stage: str, amount: Optional[float] = None) -> StageUpdateResult:
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute("SELECT stage FROM deals WHERE id = ?", (deal_id,)).fetchone()
        if row is None:
            return StageUpdateResult(deal_id, None, stage, False)
        now = datetime.now(timezone.utc).isoformat()
        if amount is None:
            conn.execute("UPDATE deals SET stage = ?, updated_at = ? WHERE id = ?", (stage, now, deal_id))
        else:
            conn.execute(
                "UPDATE deals SET stage = ?, amount = ?, updated_at = ? WHERE id = ?",
                (stage, amount, now, deal_id),
            )
        conn.commit()
        return StageUpdateResult(deal_id, row[0], stage, True)
    finally:
        conn.close()

import sqlite3

DB_PATH = "crm.db"


def _contact_exists(conn, contact_id):
    row = conn.execute("SELECT 1 FROM contacts WHERE id = ?", (contact_id,)).fetchone()
    return row is not None


def move_deals_to_contact(source_contact_id: int, target_contact_id: int) -> dict:
    if source_contact_id == target_contact_id:
        return {"moved": 0, "error": "source and target are the same"}
    conn = sqlite3.connect(DB_PATH)
    try:
        if not _contact_exists(conn, source_contact_id):
            return {"moved": 0, "error": "source contact not found"}
        if not _contact_exists(conn, target_contact_id):
            return {"moved": 0, "error": "target contact not found"}
        cur = conn.execute(
            "UPDATE deals SET contact_id = ? WHERE contact_id = ?",
            (target_contact_id, source_contact_id),
        )
        conn.commit()
        return {"moved": cur.rowcount, "from": source_contact_id, "to": target_contact_id}
    finally:
        conn.close()
